         if (phoneOnly && !explicitOnline) return TtsSpeaker.systemEngineInstalled(context)
         return when (enginePref) {
             TtsSpeaker.ENGINE_GOOGLE_WEB,
             TtsSpeaker.ENGINE_EDGE_TTS,
             TtsSpeaker.ENGINE_ELEVENLABS,
             -> online
